CREATE TABLE IF NOT EXISTS premium_detail_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, route TEXT NOT NULL, component TEXT, category TEXT NOT NULL, description TEXT NOT NULL, implemented BOOLEAN DEFAULT FALSE, priority TEXT NOT NULL DEFAULT 'medium', created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL, implemented_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS premium_detail_audits (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, route TEXT NOT NULL, total_details INTEGER DEFAULT 0, implemented INTEGER DEFAULT 0, missing INTEGER DEFAULT 0, score INTEGER DEFAULT 0, audited_at TIMESTAMPTZ DEFAULT NOW() NOT NULL);
